// LeadFlow Free - step 1: paste a real (messy) lead export here.
// The header row is required; columns are mapped by name, so the order does not matter.
// Sample rows are synthetic. Replace them with your own export, or put
// "Read/Write Files from Disk" + "Extract from File" (CSV) in front of this node
// and use the CSV text as the csv field.
const csv = [
  'First Name,Last-Name ,E-MAIL ,Company Name,Phone',
  '  Ana ,Kovač,ANA.KOVAC@PrimaStudio.rs ,Prima Studio,+381 11 123 4567',
  'Marko,Petrović,marko.petrovic@ petroco.rs,Petro Co d.o.o.,',
  'Sara,Alić,sara@alfa.rs,Alfa,"+381 60 111 2222"',
  ',Nikolić,,Beta DOO,060 333 4444',
  'Jürgen,Müller,j.mueller@muller-gmbh.de,Müller GmbH,+49 30 555',
].join('\n');

return [{ json: { csv } }];

// LeadFlow Free - step 2: split records, find the real header row, trim and validate.
//
// Three ordinary export shapes used to break this step, all of them measured on 2026-11-13:
//   1. a title row above the header ("Kontakti iz Pipedrive", "Export 10.11.2026") pushed every
//      column one record down, so the whole file came back as rejected rows;
//   2. a quoted note containing a line break was split at the newline - the note was cut in half
//      and its second half appeared in the report as an extra row that was never in the file;
//   3. splitting on "," ";" and tab inside ONE line meant a semicolon export (every European
//      Excel default) or an unquoted "Prima, Inc." landed in the wrong columns.
// So this node picks one delimiter for the whole file, reads records that may span lines, and
// treats the first record that looks like a header (a cell containing "mail") as the header,
// searching the first 20 records. Nothing leaves the n8n instance: no credentials, no HTTP.

var LF_ALIAS = {
  email: ['email', 'emailaddress', 'emailaddr', 'mail', 'email1', 'email2', 'workemail', 'businessemail',
    'primaryemail', 'contactemail', 'emailwork', 'emailoffice', 'emailbusiness', 'emailadresa'],
  first: ['firstname', 'first', 'givenname', 'forename', 'ime'],
  last: ['lastname', 'last', 'surname', 'familyname', 'prezime'],
  name: ['name', 'fullname', 'contactname', 'displayname', 'imeprezime', 'imeiprezime'],
  company: ['company', 'companyname', 'organization', 'organizationname', 'organisation', 'org', 'firma',
    'account', 'accountname', 'employer'],
  phone: ['phone', 'mobile', 'tel', 'telephone', 'phonenumber', 'telefon', 'mobitel']
};
var LF_OUT = { first: 'first_name', last: 'last_name', name: 'full_name' };

function lfKey(h) { return String(h === undefined || h === null ? '' : h).toLowerCase().replace(/[^a-z]/g, ''); }

// One record can span several physical lines, because a quoted cell may contain a newline.
function lfRecords(text, delim) {
  var s = String(text || '').replace(/\r\n?/g, '\n');
  var out = [], cells = [], cur = '', quoted = false;
  for (var i = 0; i < s.length; i++) {
    var c = s.charAt(i);
    if (quoted) {
      if (c === '"') { if (s.charAt(i + 1) === '"') { cur += '"'; i++; } else { quoted = false; } }
      else { cur += c; }
    } else if (c === '"') { quoted = true; }
    else if (c === delim) { cells.push(cur); cur = ''; }
    else if (c === '\n') { cells.push(cur); out.push(cells); cells = []; cur = ''; }
    else { cur += c; }
  }
  cells.push(cur);
  out.push(cells);
  return out.filter(function (r) {
    return r.some(function (v) { return String(v).trim() !== ''; });
  });
}

// The delimiter is whichever one makes the file look like a table: the same column count on most
// records. A comma CSV whose note cells contain semicolons wins on "," and loses on ";", and a
// Serbian/European Excel export wins the other way round. Do not decide per line.
function lfPickDelimiter(text) {
  var best = ',', bestScore = -1;
  [',', ';', '\t'].forEach(function (d) {
    var recs = lfRecords(text, d);
    if (!recs.length) return;
    var counts = {}, modal = 0, modalCount = 0;
    recs.forEach(function (r) {
      var n = r.length;
      counts[n] = (counts[n] || 0) + 1;
      if (counts[n] > modalCount) { modalCount = counts[n]; modal = n; }
    });
    if (modal < 2) return;
    var score = (modal - 1) * (modalCount / recs.length);
    if (score > bestScore) { bestScore = score; best = d; }
  });
  return best;
}

function lfFind(keys, names) {
  for (var i = 0; i < names.length; i++) {
    var at = keys.indexOf(names[i]);
    if (at > -1) return at;
  }
  return -1;
}

var EMAIL = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;

var csv = String($json.csv || '').replace(/^\uFEFF/, '');
if (!csv.trim()) return [{ json: { headers: [], rows_in: 0, cleaned: [], rejected: [] } }];

var delim = lfPickDelimiter(csv);
var recs = lfRecords(csv, delim);
if (recs.length < 2) return [{ json: { headers: [], rows_in: 0, cleaned: [], rejected: [] } }];

var headerAt = 0;
for (var hr = 0; hr < Math.min(recs.length, 20); hr++) {
  if (recs[hr].length < 2) continue;
  var probe = recs[hr].map(lfKey);
  if (probe.some(function (k) { return k.indexOf('mail') > -1; })) { headerAt = hr; break; }
}
var rawHead = recs[headerAt];
var headKeys = rawHead.map(lfKey);
var idx = {};
Object.keys(LF_ALIAS).forEach(function (f) { idx[f] = lfFind(headKeys, LF_ALIAS[f]); });

if (idx.email === -1) {
  throw new Error('No email column found in the first ' + Math.min(recs.length, 20) +
    ' rows. Headers seen: "' + rawHead.join('", "') + '". Rename the address column to "Email" ' +
    '(or "E-mail adresa", "Work Email") and run again. A .xlsx file has to be saved as CSV first.');
}

var used = {};
var headers = rawHead.map(function (label, i) {
  var k = lfKey(label), field = '';
  Object.keys(LF_ALIAS).forEach(function (f) { if (!field && LF_ALIAS[f].indexOf(k) > -1) field = f; });
  field = LF_OUT[field] || field || ('column_' + (i + 1));
  if (used[field]) { used[field]++; field = field + '_' + used[field]; } else { used[field] = 1; }
  return field;
});

var cleaned = [];
var rejected = [];

for (var n = headerAt + 1; n < recs.length; n++) {
  var cells = recs[n];
  var row = {};
  headers.forEach(function (field, i) {
    row[field] = String(cells[i] === undefined ? '' : cells[i]).trim();
  });

  row.first_name = row.first_name || '';
  row.last_name = row.last_name || '';
  if (!row.first_name && !row.last_name && row.full_name) {
    var words = row.full_name.split(/\s+/).filter(Boolean);
    row.first_name = words.shift() || '';
    row.last_name = words.join(' ');
  }
  var rawEmail = row.email || '';
  row.email = rawEmail.toLowerCase().replace(/\s+/g, '');
  row.company = row.company || '';

  if (!row.email) {
    rejected.push({ name: [row.first_name, row.last_name].join(' ').trim(), reason: 'no email in this row' });
    continue;
  }
  if (!EMAIL.test(row.email)) {
    rejected.push({ name: [row.first_name, row.last_name].join(' ').trim(), reason: 'email is not usable: "' + rawEmail + '"' });
    continue;
  }
  row.domain = row.email.split('@')[1];
  row.full_name = [row.first_name, row.last_name].join(' ').trim();
  cleaned.push(row);
}

return [{ json: { headers: headers, rows_in: recs.length - headerAt - 1, cleaned: cleaned, rejected: rejected } }];

// LeadFlow Free - step 3: one readable report instead of a wall of items.
const input = $input.first().json;
const cleaned = input.cleaned || [];
const rejected = input.rejected || [];
const rowsIn = input.rows_in || 0;
const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many);

return [{
  json: {
    rows_in: rowsIn,
    valid_rows: cleaned.length,
    rejected_rows: rejected.length,
    note: plural(cleaned.length, 'row is', 'rows are') + ' importable out of ' + rowsIn +
      '; ' + plural(rejected.length, 'row could', 'rows could') + ' not be fixed' +
      (rejected.length ? ' and ' + (rejected.length === 1 ? 'is' : 'are') + ' listed in rejected with a reason.' : '.'),
    cleaned_leads: cleaned,
    rejected,
  },
}];
